import React from "react";
import { useEffect } from "react";
import { useParams } from "react-router-dom";
import { useAuth } from "src/hooks/useAuth";
import QuoteForm from "src/views/pages/ITSolutionDetails/ITSolutionGetQuote/QuoteForm";

const ITSolutionGetQuotePage = () => {
  const { setSlug, setITSolutionId } = useAuth();
  const { id } = useParams();
  const name = id.split("-").slice(0, -1).join("-");
  const itSolutionId = id.split("-").pop();

  const cleanAndCapitalizeName = (str) =>
    str
      .replace(/-+/g, " ") // Replace one or more hyphens with a single space
      .trim() // Remove leading or trailing spaces
      .replace(/\b\w/g, (char) => char.toUpperCase());
  useEffect(() => {
    window.scrollTo(0, 0); // Scroll to the top when the component mounts
    setITSolutionId(itSolutionId);
    setSlug(name);
    document.title = `DWIT ${cleanAndCapitalizeName(name)} Get Quote`;
  }, []);

  return (
    <>
      <QuoteForm />
    </>
  );
};

export default ITSolutionGetQuotePage;
